CREATE TABLE dialect23_inventory (item_id INTEGER PRIMARY KEY, item_name TEXT NOT NULL, quantity INTEGER NOT NULL);
INSERT INTO dialect23_inventory VALUES (1, 'Cable', 20), (2, 'Notebook', 50);
SELECT item_name, CASE WHEN quantity < 10 THEN 'Low stock' ELSE 'Available' END AS stock_state FROM dialect23_inventory ORDER BY item_id;

